        {
          host,
          storyId,
          agentType,
          phase,
          promptText,
          reviewRunId,
          lane,
          timeoutMs,
          deadlineMs: deadlineMs ?? timeoutMs,
          cwd: ctx.root,
          root: ctx.root,
          projectRootHash: projectRootHashFor(ctx.root),
          ...(formalReviewBinding
            ? { profile: 'managed_reviewer', reviewBinding: formalReviewBinding, isolateManagedReview: true }
