    const primary = inventory
      .split('\0')
      .find(field => field.startsWith('worktree '))
      ?.slice('worktree '.length)
      .trim();
    if (primary) {
      const resolved = resolve(primary);
      canonicalRuntimeProjectRootCache.set(fallback, resolved);
      return resolved;
    }
  } catch {
    // Non-git or incomplete layouts retain the caller-provided project root.
  }
  // Deliberately NOT cached: see the note above -- a transient failure must not
  // pin the fallback for the process lifetime.
  return fallback;
}

